arguments.command:
curl -s -X POST https://slack.com/api/conversations.list -d token="***" -d types=public_channel -d exclude_archived=true | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERROR:', d.get('error')); sys.exit()
for c in d['channels']:
    if 'launch' in c['name']:
        print(c['id'], c['name'], c.get('is_archived'))
"

